mapper.select:
SELECT ri.id, ri.room_number, ri.rent, ai.id apartment_id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release FROM room_info ri JOIN apartment_info ai ON ri.apartment_id = ai.id
ri.is_deleted = 0 and ri.is_release = 1 and ai.is_deleted = 0 and ai.is_release = 1 and ri.id not in (SELECT room_id FROM lease_agreement WHERE is_deleted = 0 and status in (1, 2, 5, 7))
and ai.province_id = #{queryVo.provinceId}
and ai.city_id = #{queryVo.cityId}
and ai.district_id = #{queryVo.districtId}
and ri.rent >= #{qureyVo.minRent}
and ri.rent <= #{qureyVo.maxRent}
and ri.id in (SELECT room_id FROM room_payment_type WHERE payment_type_id = #{qureyVo.paymentTypeId} and is_deleted = 0)
order by ri.rent #{qureyVo.orderType}
